  function reportMenu(label,items,kind=""){
    return `<details class="report-action-menu ${kind}"><summary class="secondary report-menu-trigger">${label} <span aria-hidden="true">⌄</span></summary><div class="report-menu-panel">${items}</div></details>`;
  }
  function reportCards(rows,level,archived=false){
    return rows.length?rows.map(r=>{
      const downloads=reportMenu("↓ Скачать",`<button class="secondary report-download" data-report-action="exportFormat" data-format="xlsx" data-id="${r.id}">Excel (XLSX)</button><button class="secondary report-download" data-report-action="exportFormat" data-format="pdf" data-id="${r.id}">PDF</button><button class="secondary report-download" data-report-action="exportFormat" data-format="docx" data-id="${r.id}">Word (DOCX)</button>`,`download`);
      const online=!archived?reportMenu("▣ Online",`<button class="secondary report-online" data-report-action="excelOnlineReport" data-id="${r.id}" title="Открыть XLSX в Excel Online"><span class="office-mark">X</span> Excel Online</button><button class="secondary report-online" data-report-action="wordOnlineReport" data-id="${r.id}" title="Открыть DOCX в Word Online"><span class="office-mark">W</span> Word Online</button>`,`online`):"";
      const management=level>=2?reportMenu("⋯ Действия",`<button class="secondary" data-report-action="renameReport" data-id="${r.id}">✎ Переименовать</button><button class="secondary" data-report-action="moveReport" data-id="${r.id}">↗ Переместить</button>${archived?`<button class="primary" data-report-action="restore" data-id="${r.id}">Восстановить</button><button class="danger-outline" data-report-action="deleteReport" data-id="${r.id}">Удалить навсегда</button>`:`<button class="danger-outline" data-report-action="archive" data-id="${r.id}">В архив</button>`}`,`management`):"";
      return `<article class="report-card" data-folder-id="${r.folder_id||""}"><div class="report-card-main" data-report-action="open" data-id="${r.id}"><strong>${esc(r.title)}</strong><small>Версия ${r.version} · ${formatKedoDateTime(r.updated_at)}</small></div><div class="reports-actions">${downloads}${online}${management}</div></article>`;
    }).join(""):`<div class="report-empty">${archived?"Архив отчётов пуст.":"Отчётов пока нет."}</div>`;
  }
  function reportBytes(value){const bytes=Number(value)||0;if(bytes<1024)return `${bytes} Б`;if(bytes<1024**2)return `${(bytes/1024).toFixed(1)} КБ`;if(bytes<1024**3)return `${(bytes/1024**2).toFixed(1)} МБ`;return `${(bytes/1024**3).toFixed(2)} ГБ`;}
  function localIso(value){const date=value instanceof Date?value:new Date(value);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;}
  function reportPeriodPayload(){const type=$("reportPeriodType")?.value||"all",anchor=new Date(`${$("reportPeriodAnchor")?.value||localIso(new Date())}T12:00:00`);let from=null,to=null;if(type==="month"){from=new Date(anchor.getFullYear(),anchor.getMonth(),1);to=new Date(anchor.getFullYear(),anchor.getMonth()+1,0);}else if(type==="quarter"){const start=Math.floor(anchor.getMonth()/3)*3;from=new Date(anchor.getFullYear(),start,1);to=new Date(anchor.getFullYear(),start+3,0);}else if(type==="year"){from=new Date(anchor.getFullYear(),0,1);to=new Date(anchor.getFullYear(),11,31);}else if(type==="custom"){from=$("reportDateFrom")?.value||null;to=$("reportDateTo")?.value||null;}return {documentFolderId:Number($("folderReportSelect")?.value)||null,reportFolderId:Number($("reportFolderSelect")?.value)||null,title:$("folderReportTitle")?.value.trim()||null,includeSubfolders:Boolean($("folderReportNested")?.checked),periodType:type,dateFrom:from instanceof Date?localIso(from):from,dateTo:to instanceof Date?localIso(to):to};}
  function setupReportPeriodControls(folderSelect,titleInput){const type=$("reportPeriodType"),anchor=$("reportPeriodAnchor"),anchorField=$("reportPeriodAnchorField"),dates=$("reportCustomDates"),from=$("reportDateFrom"),to=$("reportDateTo"),hint=$("reportPeriodHint");anchor.value=localIso(new Date());const monthStart=new Date();monthStart.setDate(1);from.value=localIso(monthStart);to.value=localIso(new Date(monthStart.getFullYear(),monthStart.getMonth()+1,0));const sync=()=>{anchorField.hidden=type.value==="all"||type.value==="custom";dates.hidden=type.value!=="custom";const payload=reportPeriodPayload(),caption=payload.dateFrom?`${new Date(payload.dateFrom+"T00:00:00").toLocaleDateString("ru-RU")}–${new Date(payload.dateTo+"T00:00:00").toLocaleDateString("ru-RU")}`:"всё время";hint.textContent=`Будут отобраны документы за ${caption}. Дата документа имеет приоритет, иначе используется дата создания.`;if(!titleInput.value||titleInput.dataset.suggested!=="false"){const source=folderSelect.value?`папке «${folderSelect.selectedOptions[0]?.dataset.name||""}»`:"всему архиву";titleInput.value=`Отчёт по ${source} за ${caption}`;titleInput.dataset.suggested="true";}};[type,anchor,from,to,folderSelect].forEach(control=>control?.addEventListener("change",sync));titleInput.addEventListener("input",()=>{titleInput.dataset.suggested="false";});sync();}
  async function quickPeriod(type){const control=$("reportPeriodType"),anchor=$("reportPeriodAnchor"),from=$("reportDateFrom"),to=$("reportDateTo");if(type==="halfyear"){const now=new Date(),start=now.getMonth()<6?new Date(now.getFullYear(),0,1):new Date(now.getFullYear(),6,1);control.value="custom";from.value=localIso(start);to.value=localIso(new Date(start.getFullYear(),start.getMonth()+6,0));}else{control.value=type;anchor.value=localIso(new Date());}control.dispatchEvent(new Event("change"));const payload=reportPeriodPayload();payload.title=null;const button=document.querySelector(`[data-report-action="quickPeriod"][data-period="${type}"]`);if(button){button.disabled=true;button.textContent="Формируем…";}try{const report=await api("/api/reports/from-period",{method:"POST",...jbody(payload)});await openReport(report.id);}finally{if(button){button.disabled=false;button.textContent={month:"Месячный",quarter:"Квартальный",halfyear:"Полугодовой",year:"Годовой"}[type]||"Готово";}}}
  function renderFolderReportPreview(data){const preview=$("folderReportPreview"),summary=$("folderReportSummary"),max=Math.max(1,...data.summary.types.map(item=>item.count));preview.innerHTML=data.items.length?`<table><thead><tr><th>Тип</th><th>Название</th><th>Номер</th><th>Папка</th><th>Размер</th><th>Изменён</th></tr></thead><tbody>${data.items.map(item=>`<tr><td>${esc((item.extension||item.type).toUpperCase())}</td><td>${esc(item.title)}</td><td>${esc(item.number||"—")}</td><td>${esc(item.folder)}</td><td>${reportBytes(item.size)}</td><td>${formatKedoDateTime(item.updatedAt)}</td></tr>`).join("")}</tbody></table>`:`<div class="folder-preview-placeholder">В выбранной папке нет доступных документов.</div>`;summary.innerHTML=`<div class="reports-panel-title"><h2>Сводка папки</h2></div><div class="summary-path">▣ ${esc(data.folder.path)}</div><div class="summary-metrics"><div class="summary-metric"><span>Файлов</span><b>${data.summary.documents}</b></div><div class="summary-metric"><span>Вложенных папок</span><b>${data.summary.folders}</b></div><div class="summary-metric"><span>Общий размер</span><b>${reportBytes(data.summary.size)}</b></div><div class="summary-metric"><span>Последнее изменение</span><b>${data.summary.lastChanged?formatKedoDateTime(data.summary.lastChanged):"—"}</b></div></div><div class="summary-types">${data.summary.types.slice(0,8).map(item=>`<div class="summary-type"><span class="summary-type-badge">${esc(item.type)}</span><span class="summary-type-bar"><i style="width:${Math.round(item.count/max*100)}%"></i></span><b>${item.count}</b></div>`).join("")}</div>`;document.querySelectorAll(".report-builder-tab").forEach((tab,index)=>tab.classList.toggle("active",index===1));}
  function renderPeriodReportPreview(data){renderFolderReportPreview(data);const summary=$("folderReportSummary");if(!summary)return;const heading=summary.querySelector("h2");if(heading)heading.textContent="Сводка отчёта";if(data.period?.caption)summary.querySelector(".summary-path")?.insertAdjacentHTML("afterend",`<div class="summary-metric"><span>Период</span><b>${esc(data.period.caption)}</b></div>`);}

  async function showFolderReportDialog(){
    const result=await api("/api/documents/folders?tree=true"),folders=result.items||[];
    if(!folders.length)return kedoAlert("В архиве пока нет доступных папок.");
    const byId=new Map(folders.map(folder=>[Number(folder.id),folder]));
    const pathFor=folder=>{const names=[],seen=new Set();let item=folder;while(item&&!seen.has(Number(item.id))){seen.add(Number(item.id));names.unshift(item.name);item=byId.get(Number(item.parent_id));}return names.join(" / ");};
    const options=folders.map(folder=>({folder,path:pathFor(folder)})).sort((a,b)=>a.path.localeCompare(b.path,"ru"));
    const modal=document.createElement("div");modal.className="folder-report-modal";modal.innerHTML=`<form class="folder-report-card"><h2>Сформировать отчёт по папке</h2><p>Документы из архива станут строками обычного редактируемого отчёта.</p><label class="folder-report-field">Папка архива<select name="folderId" required>${options.map(({folder,path})=>`<option value="${folder.id}" data-name="${esc(folder.name)}" data-count="${Number(folder.document_count)||0}">${esc(path)} · ${Number(folder.document_count)||0} док.</option>`).join("")}</select></label><label class="folder-report-field">Название отчёта<input name="title" type="text" maxlength="500" placeholder="Заполнится автоматически"></label><label class="folder-report-check"><input name="nested" type="checkbox" checked> Включить документы из вложенных папок</label><div class="folder-report-summary">В отчёт попадут только документы и вложенные папки, доступные текущему пользователю.</div><div class="folder-report-actions"><button type="button" class="secondary" data-close>Отмена</button><button type="submit" class="primary">Сформировать отчёт</button></div></form>`;
    document.body.appendChild(modal);document.body.classList.add("reports-modal-open");const form=modal.querySelector("form"),select=form.elements.folderId,title=form.elements.title,submit=form.querySelector('[type="submit"]');
    const suggest=()=>{const option=select.selectedOptions[0];if(!title.value||title.dataset.suggested==="true"){title.value=`Отчёт по папке: ${option.dataset.name}`;title.dataset.suggested="true";}};suggest();select.addEventListener("change",suggest);title.addEventListener("input",()=>{title.dataset.suggested="false";});
    const close=()=>{modal.remove();document.body.classList.remove("reports-modal-open");};modal.querySelector("[data-close]").onclick=close;modal.addEventListener("click",event=>{if(event.target===modal)close();});
    form.onsubmit=async event=>{event.preventDefault();submit.disabled=true;submit.textContent="Формируем…";try{const report=await api("/api/reports/from-document-folder",{method:"POST",...jbody({documentFolderId:Number(select.value),title:title.value.trim(),includeSubfolders:form.elements.nested.checked})});close();await openReport(report.id);}catch(error){submit.disabled=false;submit.textContent="Сформировать отчёт";kedoAlert(error.message);}};
  }

  async function openReport(id){
    const [report,publicLink]=await Promise.all([api(`/api/reports/${id}`),api(`/api/public-links/reports/${id}`).catch(()=>null)]);current=report;current.publicLink=publicLink;activeSheetId=activeSheetId&&current.sheets.some(x=>x.id===activeSheetId)?activeSheetId:current.sheets[0]?.id;
    const sheet=activeSheet();
    if(state.reportsLevel>=2&&sheet&&!sheet.columns.length&&!sheet.rows.length){
      await batch(blankSheetOperations(sheet.id));
      const refreshed=await api(`/api/reports/${id}`);current={...refreshed,publicLink:current.publicLink};
    }
    drawEditor();
  }
  function activeSheet(){return current?.sheets.find(x=>x.id===activeSheetId);}
  function columnLetter(index){let value="";for(let n=index+1;n>0;n=Math.floor((n-1)/26))value=String.fromCharCode(65+(n-1)%26)+value;return value;}
  function typeLabel(type){return ({text:"Текст",number:"Число",date:"Дата",flag:"Флаг",list:"Список",link:"Ссылка",employee:"Сотрудник",department:"Подразделение",document:"Документ"})[type]||"Текст";}
  function valueText(value,col){if(value==null)return "";if(["document","link"].includes(col.column_type)&&typeof value==="object")return value.title||value.label||value.name||value.url||"Документ";if(typeof value==="object")return JSON.stringify(value);return String(value);}
